require __DIR__.'/app/bootstrap.php';require_user();$action=$_GET['action']??'';$pid=(int)($_GET['product']??0);if($action==='toggle'&&$pid>0){$s=db()->prepare('SELECT id FROM favorites WHERE user_id=? AND product_id=?');$s->execute([user_id(),$pid]);$id=$s->fetchColumn();if($id){db()->prepare('DELETE FROM favorites WHERE id=?')->execute([$id]);flash('success','Ürün favorilerden çıkarıldı.');}else{db()->prepare('INSERT INTO favorites(user_id,product_id,created_at) VALUES(?,?,NOW())')->execute([user_id(),$pid]);flash('success','Ürün favorilerinize eklendi.');}$back=$_SERVER['HTTP_REFERER']??app_url('favorites.php');header('Location: '.$back);exit;}
$s=db()->prepare("SELECT p.*,b.name brand_name,c.name category_name FROM favorites f JOIN products p ON p.id=f.product_id LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN categories c ON c.id=p.category_id WHERE f.user_id=? AND p.is_active=1 ORDER BY f.id DESC");$s->execute([user_id()]);$products=$s->fetchAll();$pageTitle='Favorilerim | TOPLUCA';require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="<?=app_url()?>">Ana Sayfa</a><span>›</span><span>Favoriler</span></div><h1>Favorilerim</h1><p><?=count($products)?> ürün</p></div></section><section class="section"><div class="container"><?php if(!$products):?><div class="empty">Henüz favori ürününüz yok.</div><?php else:?><div class="products-grid"><?php foreach($products as $p){require __DIR__.'/includes/product-card.php';}?></div><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>